(365, 3, '2025-07-12 10:58:37', '2025-07-12 13:58:37', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/*\\n * Post CSS: start\\n */\\n.ast-separate-container .ast-single-related-posts-container {\\n\\tborder-top:1px solid var(--ast-global-color-3);\\n}\\n\\n.post-navigation {\\n\\tdisplay:none;\\n}\\n/*\\n * Post CSS: end\\n */\\n\\n.cnt-image {\\n\\tdisplay:block;\\n\\tmargin:0 auto!important;\\n\\twidth:150px!important;\\n}\\n\\n.form-footer .wpcf7-response-output {\\n\\tdisplay:none;\\n}\\n\\n/*\\n * snippet_list_authors: start\\n */\\n.authors-list .items {\\n\\tdisplay:flex;\\n\\toverflow-x: auto;\\n\\tlist-style:none;\\n\\tgap:20px;\\n\\tmax-width:100%;\\n\\tjustify-content:center;\\n}\\n\\n.authors-list li {\\n\\twidth:100px;\\n\\tflex: 0 0 auto;\\n}\\n\\n.ast-single-post .entry-content .authors-list a {\\n\\ttext-decoration:none;\\n\\ttext-align:center;\\n}\\n\\n.authors-list img {\\n\\tdisplay:block;\\n\\twidth:150px;\\n\\tborder-radius:50%;\\n\\tmargin-bottom:20px;\\n}\\n\\n.authors-list p {\\n\\tmargin-bottom:0;\\n}\\n/*\\n * snippet_list_authors: end\\n */\\n\\n/*\\n * Author page: start\\n */\\n.ppma-page-title.page-title {\\n\\ttext-indent:-100px;\\n\\toverflow:hidden;\\n}\\n/*\\n * Author page: end\\n */\\n\\n@media (min-width:768px) {\\n\\t\\t.ast-container #secondary .sidebar-main [id^=\\\"block\\\"].widget  {\\n\\t\\tpadding:0 0 0 10px;\\n\\t}\\n\\t\\n\\t.authors-list li {\\n\\t\\twidth:150px;\\n\\t}\\n}\\n\\n@media (min-width:1024px) {\\n\\t.cnt-image {\\n\\t\\twidth:400px!important;\\n\\t}\\t\\n\\n\\t/*\\n\\t * Author page: start\\n\\t */\\n\\t.ppma-page-title.page-title {\\n\\t\\ttext-indent:-120px;\\n\\t}\\n\\t/*\\n\\t * Author page: end\\n\\t */\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-07-12 13:58:37\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'e671cf1a-b3ca-4feb-8e5b-3dfcb5175e44', '', '', '2025-07-12 10:58:37', '2025-07-12 13:58:37', '', 0, 'https://alura.test/?p=365', 0, 'customize_changeset', '', 0),
(366, 1, '2025-07-12 10:58:37', '2025-07-12 13:58:37', '/*\n * Post CSS: start\n */\n.ast-separate-container .ast-single-related-posts-container {\n	border-top:1px solid var(--ast-global-color-3);\n}\n\n.post-navigation {\n	display:none;\n}\n/*\n * Post CSS: end\n */\n\n.cnt-image {\n	display:block;\n	margin:0 auto!important;\n	width:150px!important;\n}\n\n.form-footer .wpcf7-response-output {\n	display:none;\n}\n\n/*\n * snippet_list_authors: start\n */\n.authors-list .items {\n	display:flex;\n	overflow-x: auto;\n	list-style:none;\n	gap:20px;\n	max-width:100%;\n	justify-content:center;\n}\n\n.authors-list li {\n	width:100px;\n	flex: 0 0 auto;\n}\n\n.ast-single-post .entry-content .authors-list a {\n	text-decoration:none;\n	text-align:center;\n}\n\n.authors-list img {\n	display:block;\n	width:150px;\n	border-radius:50%;\n	margin-bottom:20px;\n}\n\n.authors-list p {\n	margin-bottom:0;\n}\n/*\n * snippet_list_authors: end\n */\n\n/*\n * Author page: start\n */\n.ppma-page-title.page-title {\n	text-indent:-100px;\n	overflow:hidden;\n}\n/*\n * Author page: end\n */\n\n@media (min-width:768px) {\n		.ast-container #secondary .sidebar-main [id^=\"block\"].widget  {\n		padding:0 0 0 10px;\n	}\n	\n	.authors-list li {\n		width:150px;\n	}\n}\n\n@media (min-width:1024px) {\n	.cnt-image {\n		width:400px!important;\n	}	\n\n	/*\n	 * Author page: start\n	 */\n	.ppma-page-title.page-title {\n		text-indent:-120px;\n	}\n	/*\n	 * Author page: end\n	 */\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '170-revision-v1', '', '', '2025-07-12 10:58:37', '2025-07-12 13:58:37', '', 170, 'https://alura.test/?p=366', 0, 'revision', '', 0),
